#include <Adafruit_GFX.h>
#include "../RundeUhr/AircraftRender.h"
#include "../RundeUhr/IssRender.h"
#include "../RundeUhr/QuakeRender.h"
#include "../RundeUhr/LaunchRender.h"
#include <fstream>
#include <cassert>
void save(GFXcanvas8&g,int v){char path[80];sprintf(path,"build/thumb_%d.ppm",v);std::ofstream o(path,std::ios::binary);assert(o);o<<"P6\n240 240\n255\n";for(int i=0;i<57600;i++){assert((i%240-120)*(i%240-120)+(i/240-120)*(i/240-120)<=119*119||g.getBuffer()[i]==BG);auto p=activePalette[g.getBuffer()[i]&15];char b[]={char(((p>>11)&31)*255/31),char(((p>>5)&63)*255/63),char((p&31)*255/31)};o.write(b,3);}}
int main(){setenv("TZ",ZURICH_TZ,1);tzset();time_t now;assert(parseDate("2026-11-16",now));now+=17*3600;Config c;c.animations=false;strcpy(c.countdownDates[0],"2027-07-01");strcpy(c.countdownDates[1],"2027-03-25");strcpy(c.countdownDates[3],"2027-05-31");strcpy(c.countdownDates[4],"2026-12-25");Weather w;w.valid=true;w.received=now;w.count=3;w.days=1;w.day[0]=now;w.sunrise[0]=now-10*3600;w.sunset[0]=now-1800;for(int i=0;i<3;i++){w.hours[i]=now+(i+1)*3600;w.fields[i]=15;w.codes[i]=3;w.temps[i]=10;w.probability[i]=i==0?75:i==1?80:95;}Moon m;m.valid=true;m.lit=42;m.phase=.22;m.full=now+7*86400;FinanceData f;f.btc.valid=true;f.btc.value=54153.26;f.btc.received=now;f.btc.trend=1;for(int i=0;i<3;i++){f.fx[i].valid=true;f.fx[i].value=i==0?26.5:i==1?1.1:.95;f.fx[i].received=now;f.fx[i].trend=i==1?-1:1;}AircraftData a;a.found=a.checked=a.altValid=a.speedValid=true;a.kind=AircraftKind::Plane;a.received=a.positionAt=now;a.altitude=8230;a.speed=741;a.distance=4.9;strcpy(a.callsign,"SWR1V");strcpy(a.origin,"Zurich");strcpy(a.destination,"Alicante");GFXcanvas8 g(240,240);for(int v=0;v<VIEW_COUNT;v++){c.view=v;activePalette=palette;if(v==15){LaunchData d;d.valid=true;d.count=1;d.received=now;d.events[0].net=now+36000;strcpy(d.events[0].name,"Beispielrakete | Testmission");strcpy(d.events[0].status,"Go");strcpy(d.events[0].precision,"MIN");renderLaunch(g,d,now,true);}else if(v==14){QuakeData q;q.valid=true;q.count=1;q.generated=q.received=now;q.events[0].magnitude=5.2;q.events[0].depth=12;q.events[0].at=now-3600;strcpy(q.events[0].place,"Beispielregion");renderQuake(g,q,now,true);}else if(v==13){IssData i;i.valid=true;i.lat=48;i.lon=9;i.altitude=420;i.speed=27600;i.positionAt=i.received=now;renderIss(g,c,i,now,true);}else if(v==12)renderAircraft(g,a,now,true);else if(v>=10)renderFinance(g,c,f,now,true);else render(g,c,w,m,now,true,false,"","",0);save(g,v);}}
